# Generated by Descant: acceptance tests.
# frozen_string_literal: true

require "rails_helper"

RSpec.describe Timekeeping::Handoff::CorrectionSnapshots do
  include_context "timekeeping entry writes without transactional fixtures"

  # Issue: "Writing the same corrections again replaces them, so there is never a second snapshot for one entry and generation."
  it "leaves one correction snapshot per entry under each entry's own company after the same two-company corrections are written twice" do
    entry_a = Entry.create!(company_id: 101, project_id: 1, user_id: 1, work_date: Date.new(2026, 3, 2),
                            duration: 60.0, bill_status: "unbilled", version: 0)
    entry_b = Entry.create!(company_id: 202, project_id: 2, user_id: 2, work_date: Date.new(2026, 3, 2),
                            duration: 30.0, bill_status: "unbilled", version: 0)
    snapshots = [entry_a, entry_b].map do |entry|
      entry.attributes.slice(*(Timekeeping::OutboxFields::ENTRY_FIELDS - ["version"])).merge("locked" => true)
    end
    Timekeeping::Admission.fence!

    2.times { described_class.write!(snapshots:, version: 1, generation: 2) }

    rows = OutboxSnapshot.where(generation: 2).order(:company_id).pluck(:company_id, :id, :version)
    expect(rows).to eq([[101, entry_a.id, 1], [202, entry_b.id, 1]])
  end
end

RSpec.describe Timekeeping::Handoff::CorrectionSnapshots do
  include_context "timekeeping entry writes without transactional fixtures"

  # An entry belongs to the company it is stored under, so a snapshot that
  # pairs company 202 with company 101's entry must not reach the outbox.
  it "refuses a correction snapshot that names another company for an entry and writes nothing" do
    entry = Entry.create!(company_id: 101, project_id: 1, user_id: 1, work_date: Date.new(2026, 3, 2),
                          duration: 60.0, bill_status: "unbilled", version: 0)
    snapshot = entry.attributes.slice(*(Timekeeping::OutboxFields::ENTRY_FIELDS - ["version"]))
      .merge("company_id" => 202, "locked" => true)
    Timekeeping::Admission.fence!

    expect { described_class.write!(snapshots: [snapshot], version: 1, generation: 2) }.to raise_error(StandardError)

    expect(OutboxSnapshot.count).to eq(0)
    expect(entry.reload.version).to eq(0)
  end
end
